node --input-type=module <<'NODE'
import fs from 'node:fs';import {validateTracker,sha256} from './scripts/remediation/board.mjs';
const path='docs/remediation/evidence/W05.07/trusted-tracker-277.json',raw=fs.readFileSync(path),expected='5613d27004bc78fd001c2c58cb5c2f1e4a10302df5b4e20563568fce4b5a5688';
